<script setup lang="ts">
import { computed, onBeforeUnmount, reactive, ref, shallowRef, watch } from 'vue';
import {FrameButton,FrameCodeBlock} from '@frame/core';
import DemoSurface from './DemoSurface.vue';
import {createDemoState,exampleValue,serializeUsage} from './demoState';
import type {ComponentDocumentation,ApiProperty} from './types';
const props=defineProps<{documentation:ComponentDocumentation}>();
const selected=ref(0),revision=ref(0),events=ref<string[]>([]);
const contract=computed(()=>props.documentation.components[selected.value]!);
const state=shallowRef(createDemoState(contract.value));
const slots=reactive<Record<string,string>>({});const drafts=reactive<Record<string,string>>({});
const activated=ref(!contract.value.name.startsWith('Terminal'));
function refresh(){state.value.dispose();state.value=createDemoState(contract.value);for(const key in slots)delete slots[key];for(const key in drafts)delete drafts[key];for(const slot of contract.value.slots)slots[slot.name]=['default','first','second'].includes(slot.name)?'Example '+slot.name+' content':'';events.value=[];activated.value=!contract.value.name.startsWith('Terminal');revision.value++;}
watch(contract,refresh);refresh();
onBeforeUnmount(()=>state.value.dispose());
const snippet=computed(()=>serializeUsage(contract.value,state.value.props,slots));
function set(name:string,input:unknown){state.value.set(name,input);}
function enable(name:string,enabled:boolean){const prop=contract.value.props.find(p=>p.name===name)!;if(!enabled){set(name,undefined);delete drafts[name];}else set(name,exampleValue(prop,contract.value.name));}
function modes(property:ApiProperty){const modes:string[]=[];if(property.type.includes('string'))modes.push('string');if(property.type.includes('number'))modes.push('number');if(property.type.includes('boolean'))modes.push('boolean');if(property.type.includes('Component'))modes.push('component');return modes;}
function mode(property:ApiProperty){return state.value.values[property.name]==='@component'&&property.type.includes('Component')?'component':typeof state.value.values[property.name];}
function changeMode(property:ApiProperty,value:string){set(property.name,value==='component'?'@component':value==='boolean'?false:value==='number'?24:'Example');}
function input(property:ApiProperty,event:Event){const element=event.target as HTMLInputElement;drafts[property.name]=element.value;const numeric=property.control==='number'||mode(property)==='number';set(property.name,numeric?(element.value.trim()?Number(element.value):NaN):element.value);}
function log(name:string,args:unknown[]){let text:string;try{text=JSON.stringify(args,(_key,value)=>value instanceof Event?{type:value.type}:value instanceof Element?value.tagName:value);}catch{text=args.map(String).join(', ');}events.value.unshift(name+'('+text+')');events.value.splice(30);}
</script>
<template><div class="documentation-demo"><header class="showcase-row"><h2>Interactive demo</h2><label v-if="documentation.components.length>1">Component <select v-model="selected"><option v-for="(item,index) in documentation.components" :key="item.name" :value="index">{{ item.name }}</option></select></label><FrameButton variant="secondary" @click="refresh">Reset</FrameButton></header><p>Change the public properties below. Optional properties begin omitted so the component uses its real defaults. Structured input is validated before it reaches the preview.</p><div class="documentation-demo-grid"><form class="documentation-demo-inputs" @submit.prevent><fieldset v-for="property in contract.props" :key="property.name"><legend><code>{{ property.name }}</code></legend><label v-if="property.default.kind!=='required'" class="documentation-use-default"><input type="checkbox" :checked="state.values[property.name]===undefined" @change="enable(property.name,!($event.target as HTMLInputElement).checked)"/>Use component default</label><select v-if="modes(property).length>1" :aria-label="property.name+' value type'" :disabled="state.values[property.name]===undefined" :value="mode(property)" @change="changeMode(property,($event.target as HTMLSelectElement).value)"><option v-for="value in modes(property)" :key="value" :value="value">{{ value }}</option></select><select v-if="property.control==='fixture'||mode(property)==='component'" :aria-label="property.name" :disabled="state.values[property.name]===undefined" :value="state.values[property.name]" @change="set(property.name,($event.target as HTMLSelectElement).value)"><option :value="exampleValue(property)">Provided {{ property.type }} fixture</option></select><input v-else-if="property.control==='boolean'||mode(property)==='boolean'" type="checkbox" :aria-label="property.name" :disabled="state.values[property.name]===undefined" :checked="!!state.values[property.name]" @change="set(property.name,($event.target as HTMLInputElement).checked)"/><select v-else-if="property.options?.length" :aria-label="property.name" :disabled="state.values[property.name]===undefined" :value="state.values[property.name]" @change="set(property.name,($event.target as HTMLSelectElement).value)"><option v-for="value in property.options" :key="value" :value="value">{{ value }}</option></select><textarea v-else-if="property.control==='json'" :aria-label="property.name" :disabled="state.values[property.name]===undefined" rows="5" spellcheck="false" :value="drafts[property.name]??JSON.stringify(state.values[property.name],null,2)" @input="drafts[property.name]=($event.target as HTMLTextAreaElement).value;set(property.name,drafts[property.name])"/><input v-else :type="property.control==='number'||mode(property)==='number'?'number':'text'" :aria-label="property.name" :disabled="state.values[property.name]===undefined" :value="drafts[property.name]??state.values[property.name]??''" @input="input(property,$event)"/><small>{{ property.description }}</small><p v-if="state.errors[property.name]" role="alert" class="documentation-error">{{ state.errors[property.name] }}</p></fieldset><fieldset v-if="contract.slots.length"><legend>Slot content</legend><label v-for="slot in contract.slots" :key="slot.name">{{ slot.name }}<input v-model="slots[slot.name]" :aria-label="slot.name+' slot content'"/></label></fieldset></form><div class="documentation-demo-result"><div class="showcase-preview"><template v-if="activated"><DemoSurface :key="contract.name+revision" :contract="contract" :values="state.props" :slot-values="slots" @event="log" @update="set"/></template><template v-else><p>Terminal activation may start a local shell in the desktop app. It never starts just by opening this tab.</p><FrameButton variant="secondary" @click="activated=true">Activate terminal preview</FrameButton></template></div><div class="documentation-event-log"><div class="showcase-row"><h3>Events and actions</h3><FrameButton @click="events=[]">Clear</FrameButton></div><ol v-if="events.length" aria-live="polite"><li v-for="(event,index) in events" :key="index"><code>{{ event }}</code></li></ol><p v-else>No events yet.</p></div></div></div><h3>Current usage</h3><FrameCodeBlock :code="snippet" language="vue" :line-numbers="true" label="Interactive demo usage"/></div></template>
